FUNCTION_BLOCK FB_RampSpeed
VAR_INPUT
    Target : REAL;
    AccelPerS : REAL := 10.0;
    DecelPerS : REAL := 20.0;
    CycleS : REAL := 0.01;
END_VAR
VAR_OUTPUT
    Output : REAL;
END_VAR

IF Output < Target THEN
    Output := MIN(Output + AccelPerS * CycleS, Target);
ELSIF Output > Target THEN
    Output := MAX(Output - DecelPerS * CycleS, Target);
END_IF;
END_FUNCTION_BLOCK
